public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        int len = str.length();
        if (len > lb.getRemaining()) {
            throw new BufferOverflowException("Buffer is too small to hold the string");
        }

        for (int i = 0; i < len; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                lb.put((byte) c);
            } else if (c <= 0x7FF) {
                lb.put((byte) (0xC0 | (c >> 6)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            } else if (c <= 0xFFFF) {
                lb.put((byte) (0xE0 | (c >> 12)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            } else {
                lb.put((byte) (0xF0 | (c >> 18)));
                lb.put((byte) (0x80 | ((c >> 12) & 0x3F)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            }
        }

        return lb;
    } catch (Exception e) {
        // Log the error
        session.getLogger().error("Error writing UTF-8 encoded string", e);
        throw new RuntimeException("Failed to write UTF-8 encoded string", e);
