public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0, n = str.length();
    while (i < n) {
        char ch = str.charAt(i++);
        if (ch == '\\' && i < n) {
            ch = str.charAt(i++);
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + ch);
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

