private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<V,E> graph){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        List<Pair<Integer,Integer>> edgeSeparatorList = new ArrayList<>();
        Set<V> nodesInEdge = Graphs.neighborListOf(graph, edge);
        for (V node : nodesInEdge) {
            Set<Set<V>> minimalSeparators = calculateMinimalSeparators(graph, node, nodesInEdge);
            for (Set<V> minimalSeparator : minimalSeparators) {
                for (V sepNode : minimalSeparator) {
                    if (sepNode != node) {
                        edgeSeparatorList.add(new Pair<>(new Pair<>(sepNode, minimalSeparator.size()), edge));
                    }
                }
            }
        }
        globalSeparatorList.add(new Pair<>(edgeSeparatorList, edge));
    }
    return globalSeparatorList;
}

